typedef unsigned int u_int;
struct vector3d { float x, y, z; };
template <int n> struct SplineCoeffs { float a[n], b[n], c[n], d[n]; };
typedef struct { SplineCoeffs<16> y, z; } WaveProfileCoeffs;
struct WavePositionHint {
	float x, z;
	float xprofile;
	u_int xcell, zcell;
	u_int xgrid, zgrid;
	WaveProfileCoeffs wpc;
};
struct nglTexture;
typedef enum { LIP_SNAP_LEFT, LIP_SNAP_RIGHT, LIP_LAUNCH } lip_splash_types;
typedef struct {
	vector3d position;
	vector3d normal;
	WavePositionHint hint;
	float age;
	bool valid;
	int hero_index;
	nglTexture *texture;
	int type;
} lip_splash_t;
class game {
	char pad[176];
	int num_players;
public:
	int get_num_players() { return num_players; }
};
extern game *g_game_ptr;
extern lip_splash_t lip_splashes[2];
extern nglTexture *fx_tex[11];

void ks_fx_create_snap_splash(const vector3d& pos, const vector3d& normal, WavePositionHint& hint, bool left, int hero_index)
{
	if (hero_index >= g_game_ptr->get_num_players())
	{
		return;
	}

	lip_splash_t *splash = 0;

	for (int i = 0; i < 2; i++)
	{
		if (!lip_splashes[i].valid)
		{
			splash = &lip_splashes[i];
			break;
		}
	}

	if (splash != 0)
	{
		splash->age = 0;
		splash->valid = true;
		splash->position = pos;
		splash->hint = hint;
		splash->normal = normal;
		splash->type = left ? LIP_SNAP_LEFT : LIP_SNAP_RIGHT;
		splash->hero_index = hero_index;
		splash->texture = fx_tex[9];
	}
}
